const s = wb.getWorksheet('raw 1');
for (let r = 4; r <= 8; r++) {
  s.getRange(`G${r}`).setValue(`=SUM(COUNTIFS('raw 1'!$A$2:$A$100000,F${r},'raw 1'!$B$2:$B$100000,{">",">","="}&0,'raw 1'!$C$2:$C$100000,{"<","=","<"}&0))`);
}
s.addAutoTable(s.getRange('A1:C9493'));
log(s.getAutoTable()?.getRange?.()?.getA1?.());
for (let r = 4; r <= 8; r++) {
  const c = s.getRange(`G${r}`).getCell();
  log(r, c.getFormula?.(), c.getValue(), c.getText?.());
  const alt = await wb.evaluate(`=SUMPRODUCT(--('raw 1'!A2:A9493=F${r}),--(('raw 1'!B2:B9493<>0)+('raw 1'!C2:C9493<>0)>0))`);
  log('alt', alt);
}
log(await wb.evaluate(`=SUM('raw 1'!G4:G8)`));

